    for(let u=uL+.25;u<uR+flare;u+=.25){const a=PU(u,vf,0),b=PU(u,vf,H);line(a,b,night?'rgba(0,0,0,.25)':'rgba(10,30,40,.18)',.5);}
    // sky reflection band
